"""Open and export reports from original Workspace source entries.

The source catalogue reads retained metadata only. A preview resolves one member
through the original verified file transport; portable export checks every member
while streaming it into a new archive. Scientific inputs and source kinds stay
under the existing Workspace.
"""
from __future__ import annotations

import base64
import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
import tempfile
import threading
from urllib.parse import quote
import zipfile

from model.common import atomic_json, digest, file_digest, read_json
from source_report_editions import ScientificReportEditions
from source_archive_ingress import IncludedSourceArchives


def member_name(value):
    if (not isinstance(value, str) or not value or "\\" in value
            or re.search(r"[\x00-\x1f\x7f]", value)):
        raise ValueError("Choose an original relative source member.")
    path = PurePosixPath(value)
    if (path.is_absolute() or path.as_posix() != value
            or any(part in ("", ".", "..") or ":" in part for part in value.split("/"))):
        raise ValueError("Source member paths must remain in their original edition.")
    return value


def entry_key(source_id):
    return hashlib.sha256(str(source_id).encode("utf-8")).hexdigest()


def inventory(entry):
    """Preserve Workspace view_path, including cross-date source companions."""
    result = {}
    for descriptor in [entry["body"], *entry.get("companions", [])]:
        name = member_name(descriptor.get("view_path") or descriptor.get("filename"))
        if (not isinstance(descriptor.get("bytes"), int) or isinstance(descriptor["bytes"], bool)
                or descriptor["bytes"] < 0
                or not re.fullmatch(r"[0-9a-f]{64}", descriptor.get("sha256", ""))):
            raise ValueError("Retained source member identity is incomplete.")
        if name in result and any(result[name][key] != descriptor[key] for key in ("bytes", "sha256")):
            raise ValueError("Two source members claim the same original view path.")
        result.setdefault(name, descriptor)
    names = set(result)
    for name in names:
        if any(parent.as_posix() in names for parent in PurePosixPath(name).parents
               if parent.as_posix() != "."):
            raise ValueError("A source member conflicts with a parent directory.")
    return result


def html_members(entry):
    primary = member_name(entry["body"].get("view_path") or entry["body"]["filename"])
    return [name for name in inventory(entry)
            if PurePosixPath(name).suffix.lower() in (".html", ".htm")
            and (name == primary or re.search(r"(^open[_-]|report|review|^index\.)",
                                              PurePosixPath(name).name, re.IGNORECASE))]


def document_policy(body):
    """Allow only original inline script bodies, inside an opaque-origin sandbox."""
    text = body.decode("utf-8-sig")
    scripts = re.findall(r"<script\b[^>]*>([\s\S]*?)</script\s*>", text, flags=re.IGNORECASE)
    hashes = sorted({
        "'sha256-" + base64.b64encode(hashlib.sha256(
            source.replace("\r\n", "\n").replace("\r", "\n").encode("utf-8")).digest()).decode("ascii") + "'"
        for source in scripts
    })
    return (
        "default-src 'none'; script-src " + (" ".join(hashes) or "'none'") + "; "
        "style-src 'self' 'unsafe-inline'; img-src 'self' data:; "
        "connect-src 'none'; object-src 'none'; frame-src 'none'; "
        "base-uri 'none'; form-action 'none'; frame-ancestors 'self'; "
        "sandbox allow-scripts allow-downloads allow-modals allow-popups allow-popups-to-escape-sandbox"
    )


# A saved report is static HTML. Its original relative source/figure links need
# the operator origin and strict file-session cookie, while scripts remain off.
SCIENTIFIC_REPORT_POLICY = (
    "default-src 'none'; script-src 'none'; style-src 'self' 'unsafe-inline'; "
    "img-src 'self' data:; connect-src 'none'; object-src 'none'; frame-src 'none'; "
    "base-uri 'none'; form-action 'none'; frame-ancestors 'self'; "
    "sandbox allow-same-origin allow-downloads allow-popups allow-popups-to-escape-sandbox"
)


def scientific_document_policy(body, view):
    if view == "report":
        return SCIENTIFIC_REPORT_POLICY
    policy = document_policy(body)
    if view == "briefing":
        # Only the byte-exact installed client_briefing template receives this
        # mode; its existing inline script hashes and all network limits remain.
        return policy.replace("sandbox allow-scripts ", "sandbox allow-same-origin allow-scripts ", 1)
    return policy


# These are ordinary source manifests shipped with the installed application.
# Additional editions use the existing --source-manifest or --source-root options.
BUNDLED_REPORT_MANIFESTS = (
    "observations/landcover_2023_2025/report-2023/source-manifest.json",
    "observations/landcover_2023_2025/report-2025/source-manifest.json",
    "observations/landcover_2023_2025/scientific-report/source-manifest.json",
    "observations/landcover_2023_2025/focal-report/source-manifest.json",
    "results/assessment-association-review-20261013/sources.json",
    "results/assessment-source-scope-review-20261013/sources.json",
    "results/assessment-association-review-20261013/observed-sources.json",
    "results/assessment-source-scope-review-20261013/observed-sources.json",
    "results/native-assessment-delivery-20261013/sources.json",
    "results/native-assessment-microbial-delivery-20261013/sources.json",
    "source/station-assessment-context/native159-source-context-20261013/sources-complete.json",
    "source/station-assessment-context/native159-source-context-20261013/sources-all-editions.json",
    "source/water_context/sources-20261013.json",
    "source/rl18151-lake-phosphorus-20261013/sources.json",
    "point_source_history.sources.json",
    "point_source_load_volume.sources.json",
    "point_source_scientific.sources.json",
    "nc_assessment_history.sources.json",
    "eighteenmile_trace_metals.sources.json",
    "source/north-carolina-assessment-2022/sources.json",
    "source/georgia-assessment-2024/publisher-savannah-20261013/sources.json",
)


def unique_report_entries(entries, *, retained=False):
    """Prefer the original document when a recipe retains its same HTML.

    Deduplication is confined to one source collection and uses the complete
    original source path plus bytes and SHA. All typed entries remain registered.
    """
    prepared = []
    for position, entry in enumerate(entries):
        if retained:
            members = inventory(entry)
            primary = member_name(entry["body"].get("view_path") or entry["body"]["filename"])
            names = html_members(entry)
        else:
            members = {member_name(row["path"]): row
                       for row in [entry, *entry.get("companions", [])]}
            primary = member_name(entry["path"])
            names = [name for name in members
                     if PurePosixPath(name).suffix.lower() in (".html", ".htm")
                     and (name == primary or re.search(
                         r"(^open[_-]|report|review|^index\.)",
                         PurePosixPath(name).name, re.IGNORECASE))]
        if not names:
            continue
        rank = (primary not in names, entry.get("role") == "OBSERVED_CONTEXT", position)
        prepared.append((rank, position, entry, names, members))
    selected, seen = [], set()
    for unused, position, entry, names, members in sorted(prepared, key=lambda row: row[0]):
        identities = {
            (members[name].get("source_path", name), members[name].get("bytes"),
             members[name].get("sha256"))
            for name in names
        }
        # Missing optional raw-manifest identity fields cannot establish sameness.
        bound = all(size is not None and sha is not None for unused_path, size, sha in identities)
        if bound and identities.issubset(seen):
            continue
        if bound:
            seen.update(identities)
        selected.append((position, entry, names))
    return [(entry, names) for unused, entry, names in sorted(selected, key=lambda row: row[0])]


def manifest_reports(value):
    """Describe each original preview once without reading source bodies."""
    return [{
        "source_id": row["id"], "title": row["title"],
        "kind": row["kind"], "role": row.get("role"),
        "vintage": row["vintage"], "documents": names,
    } for row, names in unique_report_entries(value["entries"])]


def manifest_documents(value):
    """Describe typed original documents without pretending they are HTML previews."""
    return [{
        "source_id": row["id"], "title": row["title"],
        "kind": row["kind"], "role": row.get("role"),
        "vintage": row["vintage"], "path": member_name(row["path"]),
        "scientific_report": row.get("role") == "OBSERVED_CONTEXT"
                             and row.get("kind") == "document",
    } for row in value["entries"]
      if row.get("kind") == "document" or row.get("role") == "OBSERVED_CONTEXT"]


def retained_scientific_sources(collection):
    """Keep exact original collection/source choices for the normal report composer."""
    return [{
        "source_collection_id": collection["id"], "source_id": entry["id"],
        "title": entry["title"], "vintage": entry["vintage"],
    } for entry in collection.get("entries", [])
      if entry.get("role") == "OBSERVED_CONTEXT" and entry.get("kind") == "document"]


def manifest_readiness(path, value):
    """Check installed member metadata; Workspace import verifies original bytes."""
    root = path.parent.resolve()
    members, problems = {}, []
    for row in value["entries"]:
        for item in [row, *row.get("companions", [])]:
            name = member_name(item["path"])
            prior = members.setdefault(name, dict(item))
            for key in ("bytes", "sha256"):
                incoming = item.get(key)
                if incoming is None:
                    continue
                if prior.get(key) is not None and prior[key] != incoming:
                    problems.append({"member": name, "reason": "Conflicting declared source " + key})
                else:
                    prior[key] = incoming
    for name, item in members.items():
        try:
            target = (root / name).resolve(strict=True)
            if not target.is_relative_to(root) or not target.is_file():
                raise ValueError("Source member is outside its edition or is not a file")
            expected = item.get("bytes")
            if expected is not None and (
                    not isinstance(expected, int) or isinstance(expected, bool)
                    or expected < 0 or target.stat().st_size != expected):
                raise ValueError("Installed file size differs from its declared original")
        except (OSError, ValueError) as error:
            problems.append({"member": name, "reason": str(error)})
    return {"ready": not problems, "member_count": len(members), "problems": problems}



class SourceReports:
    def __init__(self, operator, fault, source_roots=()):
        self.operator, self.Fault = operator, fault
        self.scientific = ScientificReportEditions(operator, fault)
        self._archive_lock = threading.RLock()
        self._source_roots = tuple(source_roots)
        self.included_archives = IncludedSourceArchives(
            operator, fault, Path(__file__).resolve().parents[1], self._source_roots)
        self._managed_registered_ids = set()
        self._available_editions = []
        self._discovery_issues = []
        self.refresh_registered()

    def _manifest_candidates(self, registered):
        """Use selected directories only; never traverse a scientific Workspace."""
        candidates, seen = [], set()

        def add(path, origin, *, required=False):
            path = Path(path).expanduser()
            try:
                resolved = path.resolve(strict=required)
            except OSError as error:
                self._discovery_issues.append({"manifest": path.name, "reason": str(error)})
                return
            if resolved in seen or (not required and not resolved.is_file()):
                return
            seen.add(resolved)
            candidates.append((resolved, origin))

        for row in registered.values():
            add(row["path"], "Registered source", required=True)
        application = Path(__file__).resolve().parents[1]
        for relative in BUNDLED_REPORT_MANIFESTS:
            add(application / relative, "Included with this application")
        for root_value in self._source_roots:
            root = Path(root_value).expanduser()
            if root.is_file():
                add(root, "Configured source")
                continue
            if not root.is_dir():
                self._discovery_issues.append({
                    "manifest": root.name, "reason": "Configured source directory is unavailable"
                })
                continue
            for relative in BUNDLED_REPORT_MANIFESTS:
                add(root / relative, "Configured source")
            # Accept manifest files directly inside the explicitly selected edition.
            # No recursive search or source-body read is needed.
            for pattern in ("sources*.json", "*.sources.json", "*-sources.json", "source-manifest.json"):
                for path in sorted(root.glob(pattern)):
                    add(path, "Configured source")
        return candidates

    def refresh_registered(self):
        """Populate the original operator registry, keeping explicit registrations first."""
        with self._archive_lock, self.operator.lock:
            current = self.operator.registered
            registered = {key: row for key, row in current.items()
                          if key not in self._managed_registered_ids}
            explicit_by_path = {str(Path(row["path"]).resolve()): row
                                for row in registered.values()}
            managed, available = set(), []
            self._discovery_issues = []
            for path, origin in self._manifest_candidates(registered):
                try:
                    raw = path.read_bytes()
                    value = json.loads(raw)
                    if not isinstance(value, dict) or value.get("schema") != "upstate.sources/v1":
                        continue
                    summary = self.operator._manifest_summary(value)
                    report_rows = manifest_reports(value)
                    document_rows = manifest_documents(value)
                    regional = any(row.get("role") == "SOURCE_WATER_CONTEXT"
                                   for row in value["entries"])
                    if not report_rows and not document_rows and not regional:
                        continue
                    sha = hashlib.sha256(raw).hexdigest()
                    ready = manifest_readiness(path, value)
                    explicit = explicit_by_path.get(str(path))
                    if explicit is not None:
                        key = explicit["id"]
                        if explicit["sha256"] != sha:
                            ready["ready"] = False
                            ready["problems"].append({
                                "member": path.name,
                                "reason": "Registered manifest changed; restart with its new edition"
                            })
                    else:
                        key = digest({"path": str(path), "sha256": sha})
                        if ready["ready"]:
                            existing = registered.get(key)
                            record = {
                                "id": key, "path": str(path), "sha256": sha,
                                "title": summary["title"], "entries": len(value["entries"])
                            }
                            if existing is not None and any(existing.get(field) != record[field]
                                    for field in ("id", "path", "sha256")):
                                raise ValueError("Registered source ID has a different identity")
                            registered.setdefault(key, record)
                            managed.add(key)
                    available.append({
                        "registered_id": key if ready["ready"] else None,
                        "manifest_sha256": sha, "manifest_name": path.name,
                        "title": summary["title"], "origin": origin,
                        "entry_count": len(value["entries"]), "reports": report_rows,
                        "documents": document_rows,
                        "source_ids": [row["id"] for row in value["entries"]],
                        "regional_context": regional,
                        "vintages": list(dict.fromkeys(str(row["vintage"]) for row in value["entries"])),
                        **ready,
                    })
                except (OSError, ValueError, TypeError, KeyError, self.Fault) as error:
                    self._discovery_issues.append({"manifest": path.name, "reason": str(error)})
            # Replace the dictionary atomically, retaining the original explicit order.
            self.operator.registered = registered
            self._managed_registered_ids = managed
            archive_editions, archive_issues = self.included_archives.discover()
            # A loose manifest already offers the same byte-identical import.
            available_manifest_shas = {row["manifest_sha256"] for row in available if row["ready"]}
            available.extend(row for row in archive_editions
                             if row["manifest_sha256"] not in available_manifest_shas)
            self._discovery_issues.extend(archive_issues)
            self._available_editions = available


    def _collection(self, workspace, collection_id):
        if not re.fullmatch(r"[0-9a-f]{64}", str(collection_id or "")):
            raise self.Fault("SOURCE_REPORT_EDITION", "Choose a retained source edition.")
        return self.operator.ws(workspace).retained_item("sources", collection_id)

    def _entry(self, workspace, collection_id, selected_key):
        collection = self._collection(workspace, collection_id)
        if not re.fullmatch(r"[0-9a-f]{64}", str(selected_key or "")):
            raise self.Fault("SOURCE_REPORT_ENTRY", "Choose a retained report source.")
        matches = [row for row in collection["entries"] if entry_key(row["id"]) == selected_key]
        if len(matches) != 1 or not html_members(matches[0]):
            raise self.Fault("SOURCE_REPORT_ENTRY", "This source entry has no retained HTML report.", 404)
        return collection, matches[0], inventory(matches[0])

    @staticmethod
    def _url(workspace, collection, key, name):
        identifiers = [workspace, collection, key]
        return "/api/file/source-reports/" + "/".join(quote(str(x), safe="") for x in identifiers) + "/" + quote(name, safe="/")

    def _row(self, workspace, collection, entry):
        members = inventory(entry)
        html = html_members(entry)
        key = entry_key(entry["id"])
        metadata = entry.get("metadata") if isinstance(entry.get("metadata"), dict) else {}
        related = entry.get("related_source_ids") or metadata.get("related_source_ids", [])
        return {
            "collection_id": collection["id"], "entry_key": key, "source_id": entry["id"],
            "collection_title": collection.get("title") or collection.get("scope") or collection["id"],
            "title": entry["title"], "kind": entry["kind"], "role": entry.get("role"),
            "uri": entry["uri"], "vintage": entry["vintage"],
            "captured_at": collection.get("captured_at"), "description": entry.get("description", ""),
            "body_sha256": entry["body"]["sha256"], "member_count": len(members),
            "html": [{"path": name, "bytes": members[name]["bytes"], "sha256": members[name]["sha256"],
                      "url": self._url(workspace, collection["id"], key, name)} for name in html],
            "scientific_reports": [
                {"source_collection_id": collection["id"], "source_id": candidate["id"],
                 "title": candidate["title"], "vintage": candidate["vintage"]}
                for candidate in collection.get("entries", [])
                if candidate.get("role") == "OBSERVED_CONTEXT"
                and isinstance(candidate.get("metadata"), dict)
                and isinstance(candidate["metadata"].get("related_source_ids"), list)
                and entry["id"] in candidate["metadata"]["related_source_ids"]
            ],
            "related_source_ids": related if isinstance(related, list) else [],
            "source_relationships": metadata.get("source_relationships", []),
        }

    def catalog(self, workspace, *, refresh=False):
        if refresh:
            self.refresh_registered()
        reports = []
        collections = self.operator.ws(workspace).sources()
        for collection in collections:
            for entry, unused in unique_report_entries(collection.get("entries", []), retained=True):
                reports.append(self._row(workspace, collection, entry))
        editions = []
        for original in self._available_editions:
            retained = [row for row in collections
                        if row.get("original_manifest", {}).get("sha256")
                        == original["manifest_sha256"]]
            retained_ids = {row["id"] for row in retained}
            editions.append({
                **original,
                "entry_count": (len(retained[0].get("entries", []))
                                if original.get("entry_count") is None and retained
                                else original.get("entry_count")),
                "retained_collections": [{"id": row["id"], "title": row.get("title", row["id"])}
                                         for row in retained],
                "retained_scientific_sources": [source for row in retained
                                                for source in retained_scientific_sources(row)],
                "retained_reports": [
                    {"collection_id": row["collection_id"], "entry_key": row["entry_key"],
                     "title": row["title"], "source_id": row["source_id"]}
                    for row in reports if row["collection_id"] in retained_ids
                ],
            })
        retained_editions = []
        for collection in collections:
            documents = [{
                "source_id": entry["id"], "title": entry["title"],
                "kind": entry["kind"], "role": entry.get("role"),
                "vintage": entry["vintage"],
                "scientific_report": entry.get("kind") == "document"
                                     and entry.get("role") == "OBSERVED_CONTEXT",
            } for entry in collection.get("entries", [])
              if entry.get("kind") == "document" or entry.get("role") == "OBSERVED_CONTEXT"]
            if documents:
                retained_editions.append({
                    "collection_id": collection["id"],
                    "title": collection.get("title") or collection.get("scope") or collection["id"],
                    "original_manifest_sha256": collection["original_manifest"]["sha256"],
                    "entry_count": len(collection["entries"]), "documents": documents,
                    "scientific_sources": retained_scientific_sources(collection),
                })
        return {"workspace_key": workspace, "reports": reports,
                "available_editions": editions, "retained_editions": retained_editions,
                "discovery_issues": self._discovery_issues}

    def detail(self, workspace, payload):
        collection, entry, members = self._entry(
            workspace, payload.get("collection_id"), payload.get("entry_key"))
        row = self._row(workspace, collection, entry)
        row["members"] = [{
            "path": name, "bytes": body["bytes"], "sha256": body["sha256"],
            "primary": body is entry["body"],
            "url": self._url(workspace, collection["id"], row["entry_key"], name),
        } for name, body in members.items()]
        row["original_manifest"] = self.operator._ticket(
            workspace, self.operator.ws(workspace).root / collection["original_manifest"]["object"],
            collection["original_manifest"], "Original source edition manifest")
        row["related_sources"] = [
            {"id": other["id"], "title": other["title"], "kind": other["kind"], "role": other.get("role")}
            for other in collection["entries"] if other["id"] in row["related_source_ids"]
        ]
        return {"workspace_key": workspace, "report": row}

    def _path(self, workspace, descriptor):
        root = self.operator.ws(workspace).root.resolve()
        path = (root / member_name(descriptor["object"])).resolve(strict=True)
        if not path.is_relative_to(root) or not path.is_file():
            raise self.Fault("SOURCE_REPORT_FILE", "The original retained member is absent.", 404)
        return path

    def member(self, workspace, collection_id, selected_key, name):
        _, _, members = self._entry(workspace, collection_id, selected_key)
        name = member_name(name)
        if name not in members:
            raise self.Fault("SOURCE_REPORT_MEMBER", "Choose a file retained with this report.", 404)
        descriptor = members[name]
        path = self._path(workspace, descriptor)
        policy = None
        if PurePosixPath(name).suffix.lower() in (".html", ".htm"):
            body = path.read_bytes()
            if len(body) != descriptor["bytes"] or hashlib.sha256(body).hexdigest() != descriptor["sha256"]:
                raise self.Fault("SOURCE_REPORT_CHANGED", "The retained report bytes changed.", 409)
            policy = document_policy(body)
        ticket = self.operator._ticket(workspace, path, descriptor, name)
        return ticket, policy

    def archive(self, workspace, payload):
        # Existing report callers keep their exact HTML-entry admission. A whole
        # retained collection needs no HTML member and uses the same ZIP writer.
        if "entry_key" in payload:
            collection, entry, members = self._entry(
                workspace, payload.get("collection_id"), payload["entry_key"])
        else:
            collection = self._collection(workspace, payload.get("collection_id"))
            entry = None
        ws = self.operator.ws(workspace)
        original = collection["original_manifest"]
        manifest_path = self._path(workspace, original)
        original_body = manifest_path.read_bytes()
        if len(original_body) != original["bytes"] or hashlib.sha256(original_body).hexdigest() != original["sha256"]:
            raise self.Fault("SOURCE_REPORT_CHANGED", "The original source manifest changed.", 409)
        original_manifest = json.loads(original_body)
        if entry is not None:
            selected = [row for row in original_manifest["entries"] if row["id"] == entry["id"]]
            if len(selected) != 1:
                raise self.Fault("SOURCE_REPORT_MANIFEST", "The original manifest does not identify this report.", 409)
        # Export the complete original collection, so related scientific source
        # IDs remain registered after reimport. Restore source_path here; member
        # preview uses each entry's independently normalized view_path instead.
        archive_members = {}
        retained_entries = {row["id"]: row for row in collection["entries"]}
        if set(retained_entries) != {row["id"] for row in original_manifest["entries"]}:
            raise self.Fault("SOURCE_REPORT_MANIFEST", "The retained source edition differs from its original manifest.", 409)
        for original_entry in original_manifest["entries"]:
            retained_entry = retained_entries[original_entry["id"]]
            declared = [original_entry, *original_entry.get("companions", [])]
            retained = [retained_entry["body"], *retained_entry.get("companions", [])]
            if len(declared) != len(retained):
                raise self.Fault("SOURCE_REPORT_MANIFEST", "The original companion inventory changed.", 409)
            for original_row, descriptor in zip(declared, retained):
                name = member_name(original_row["path"])
                if descriptor.get("source_path", name) != name:
                    raise self.Fault("SOURCE_REPORT_MANIFEST", "The retained source path differs from its original manifest.", 409)
                for key in ("bytes", "sha256"):
                    if key in original_row and original_row[key] != descriptor[key]:
                        raise self.Fault("SOURCE_REPORT_MANIFEST", "The original manifest identity differs: " + name, 409)
                if name in archive_members and any(archive_members[name][key] != descriptor[key] for key in ("bytes", "sha256")):
                    raise self.Fault("SOURCE_REPORT_MANIFEST", "Source entries conflict at an original path: " + name, 409)
                archive_members.setdefault(name, descriptor)
        for name in archive_members:
            if any(parent.as_posix() in archive_members for parent in PurePosixPath(name).parents
                   if parent.as_posix() != "."):
                raise self.Fault("SOURCE_REPORT_MANIFEST", "A source member conflicts with its parent directory.")
        occupied = {name.split("/", 1)[0].casefold() for name in archive_members}
        manifest_name = "sources.json"
        if manifest_name.casefold() in occupied:
            manifest_name = "report-sources-" + original["sha256"][:16] + ".json"
            while manifest_name.casefold() in occupied:
                manifest_name = "report-" + manifest_name
        # The manifest itself remains byte-exact; its original relative paths
        # resolve beside this top-level filename without adding another wrapper.
        manifest_body = original_body
        selection = {
            "collection_id": collection["id"],
            "original_manifest_sha256": original["sha256"],
            "manifest_member": manifest_name,
            "members": [{"path": name, "bytes": row["bytes"], "sha256": row["sha256"]}
                        for name, row in sorted(archive_members.items())],
        }
        identity = digest(selection)
        folder = self.operator.root / "outputs" / "source-reports"
        folder.mkdir(parents=True, exist_ok=True, mode=0o700)
        destination, metadata = folder / (identity + ".zip"), folder / (identity + ".json")
        with self._archive_lock:
            if not destination.exists() or not metadata.exists():
                fd, temporary_name = tempfile.mkstemp(prefix=identity + ".", suffix=".zip", dir=folder)
                os.close(fd)
                temporary = Path(temporary_name)
                try:
                    with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED,
                                         compresslevel=6, allowZip64=True) as archive:
                        for name, descriptor in archive_members.items():
                            path = self._path(workspace, descriptor)
                            info = zipfile.ZipInfo(name, (1980, 1, 1, 0, 0, 0))
                            info.compress_type = zipfile.ZIP_DEFLATED
                            info.external_attr = 0o100600 << 16
                            info.file_size = descriptor["bytes"]
                            sha, count = hashlib.sha256(), 0
                            with path.open("rb") as source, archive.open(info, "w", force_zip64=descriptor["bytes"] >= zipfile.ZIP64_LIMIT) as output:
                                while block := source.read(1024 * 1024):
                                    sha.update(block)
                                    count += len(block)
                                    output.write(block)
                            if count != descriptor["bytes"] or sha.hexdigest() != descriptor["sha256"]:
                                raise self.Fault("SOURCE_REPORT_CHANGED", "A retained report companion changed: " + name, 409)
                        for name, body in ((manifest_name, manifest_body),):
                            info = zipfile.ZipInfo(name, (1980, 1, 1, 0, 0, 0))
                            info.compress_type = zipfile.ZIP_DEFLATED
                            info.external_attr = 0o100600 << 16
                            archive.writestr(info, body)
                    record = {"selection": selection, "manifest_member": manifest_name,
                              "bytes": temporary.stat().st_size, "sha256": file_digest(temporary),
                              "filename": "retained-report-" + identity[:16] + ".zip"}
                    os.replace(temporary, destination)
                    atomic_json(metadata, record)
                finally:
                    temporary.unlink(missing_ok=True)
            record = read_json(metadata)
            if record.get("selection") != selection:
                raise self.Fault("SOURCE_REPORT_ARCHIVE", "The retained portable report selection changed.", 409)
        return {"workspace_key": workspace, "source_id": entry["id"] if entry is not None else None,
                "collection_id": collection["id"],
                "original_manifest_sha256": original["sha256"],
                "source_ids": [row["id"] for row in original_manifest["entries"]],
                "manifest_member": record["manifest_member"],
                "download": self.operator._ticket(workspace, destination, record, "Report and complete original source edition")}

    def read(self, workspace, operation, payload):
        if operation == "scientific-source":
            from scientific_source_reader import ScientificSourceReader
            return ScientificSourceReader(self.operator, self.Fault).detail(workspace, payload)
        if operation.startswith("scientific-"):
            return self.scientific.read(workspace, operation, payload)
        if operation == "catalog":
            return self.catalog(workspace, refresh=str(payload.get("refresh", "")).lower() in {"1", "true"})
        if operation == "included-archive-preview":
            return self.included_archives.preview(workspace, payload.get("archive_id"))
        if operation == "detail":
            return self.detail(workspace, payload)
        if operation == "archive":
            return self.archive(workspace, payload)
        raise self.Fault("SOURCE_REPORT_OPERATION", "Choose an original source report operation.", 404)

    def invoke(self, task):
        return self.scientific.invoke(task)

    def state(self, workspace):
        return self.scientific.state(workspace)

    def verify_workspace(self, workspace):
        return self.scientific.verify_workspace(workspace)

    def decorate_task(self, task):
        return self.scientific.decorate_task(task)

    def scientific_source_member(self, workspace, collection_id, source_key, name):
        from scientific_source_reader import ScientificSourceReader
        return ScientificSourceReader(self.operator, self.Fault).member(
            workspace, collection_id, source_key, name)

    def scientific_member(self, workspace, key, name):
        ticket, path, view = self.scientific.member(workspace, key, name, with_view=True)
        policy = scientific_document_policy(path.read_bytes(), view) if path.suffix.lower() in (".html", ".htm") else None
        return ticket, policy

    def briefing_member(self, workspace, key, name):
        ticket, path, view = self.scientific.briefing_member(workspace, key, name, with_view=True)
        policy = scientific_document_policy(path.read_bytes(), view) if path.suffix.lower() in (".html", ".htm") else None
        return ticket, policy

"""Saved standalone scientific editions on the original operator queue and file transport."""
from __future__ import annotations

import base64
import hashlib
import json
from pathlib import Path, PurePosixPath
from urllib.parse import quote

from model.common import (atomic_json, describe_file, digest, held, identifier,
                          read_json, relative_file, verify_file)
from model import scientific_briefing
from model import observed_context
from model import scientific_report_editions as retained_editions
from model import scientific_report_review
from model import scientific_report_capture

def _pair(row):
    return row.get("source_collection_id"), row.get("source_id")


KIND = "scientific-report-editions"
SCHEMA = "upstate.scientific-report-edition/v1"
ACTIONS = frozenset({"source-reports.render", "source-reports.export", "source-reports.briefing", "source-reports.review", "source-reports.adopt"})


class ScientificReportEditions:
    def __init__(self, operator, fault):
        self.operator, self.Fault = operator, fault

    def _directory(self, workspace, key):
        return retained_editions.directory(workspace, key)

    def _record(self, workspace, key):
        return retained_editions.record(workspace, key)

    def _inspect(self, workspace, key):
        return retained_editions.inspect(workspace, key)

    @staticmethod
    def _summary(record):
        return {name: record[name] for name in (
            "id", "title", "state", "operation_id", "source_count", "section_count",
            "figure_count", "sources")}

    def saved(self, workspace):
        folder = self.operator.ws(workspace).root / KIND
        rows = []
        for path in sorted(folder.glob("*/edition.json")):
            record, _ = self._record(self.operator.ws(workspace), path.parent.name)
            rows.append(self._summary(record))
        return rows

    def _native_studies(self, workspace):
        # Source reports also run in installations without the optional GIS desk.
        from importlib import import_module
        try:
            native = import_module("model.gis_native_study")
        except ModuleNotFoundError as error:
            if error.name != "model.gis_native_study":
                raise
            return []
        return native.choices(self.operator.ws(workspace))

    def catalog(self, workspace):
        rows = []
        for collection in self.operator.ws(workspace).sources():
            for entry in collection.get("entries", []):
                metadata = entry.get("metadata") or {}
                if (entry.get("kind") == "document"
                        and (metadata.get("report_schema") == observed_context.SCHEMA
                             or entry.get("role") == observed_context.ROLE)):
                    rows.append({"source_collection_id": collection["id"], "source_id": entry["id"],
                                 "title": entry["title"], "vintage": entry["vintage"],
                                 "uri": entry["uri"], "body_sha256": entry["body"]["sha256"],
                                 "body_bytes": entry["body"]["bytes"],
                                 "collection_title": collection.get("title", collection["id"])})
        native = {_pair(row): row for row in self._native_studies(workspace)}
        for row in rows:
            if _pair(row) in native:
                row["native_study"] = native[_pair(row)]
        captures = scientific_report_capture.catalog(self.operator.ws(workspace))
        return {"workspace_key": workspace, "sources": rows, "editions": self.saved(workspace),
                "captured_reports": captures["reports"], "capture_issues": captures["issues"]}

    def capture_preview(self, workspace, payload):
        result = scientific_report_capture.preview(
            self.operator.ws(workspace), identifier(payload.get("capture_id")))
        return {"workspace_key": workspace, **result}

    def adopt(self, workspace, payload):
        return scientific_report_capture.adopt(
            self.operator.ws(workspace), identifier(payload.get("capture_id")),
            expected_capture_sha256=identifier(payload.get("capture_sha256")),
            expected_edition_id=identifier(payload.get("edition_id")))

    def preview(self, workspace, payload):
        result = retained_editions.preview(self.operator.ws(workspace), payload)
        return {"workspace_key": workspace, **result}

    def render(self, workspace, payload):
        try:
            return retained_editions.render(self.operator.ws(workspace), payload)
        except retained_editions.PreviewChanged as error:
            raise self.Fault("SCIENTIFIC_REPORT_PREVIEW", str(error), 409) from error

    def _files(self, record, directory):
        return retained_editions.files(record, directory)

    def _url(self, workspace, key, name):
        return "/api/file/scientific-reports/" + "/".join(
            quote(str(part), safe="") for part in (workspace, key)) + "/" + quote(name, safe="/")

    def detail(self, workspace, key):
        ws = self.operator.ws(workspace)
        record, directory, result = self._inspect(ws, identifier(key))
        members = [{"role": role, **item,
                    "url": self._url(workspace, key, item["path"])}
                   for role, item in self._files(record, directory).items()]
        archive = None
        receipt = directory / "report-files.json"
        if receipt.is_file():
            item = read_json(receipt)["file"]
            verify_file(directory, item)
            archive = self.operator._ticket(workspace, directory / item["path"], item, "Complete report ZIP")
        original_pairs = {_pair(row) for row in record["sources"]}
        native_studies = [row for row in self._native_studies(workspace) if _pair(row) in original_pairs]
        return {"workspace_key": workspace, "edition": record, "files": members, "archive": archive,
                "native_studies": native_studies,
                "briefings": self.briefing_catalog(workspace, key),
                "viewer_url": next((row["url"] for row in members
                                    if row["role"] == "report_html"), None),
                "_downloads": [self.operator._ticket(workspace, relative_file(directory, row["path"]),
                                                       row, row["role"]) for row in members]}

    def member(self, workspace, key, name, *, with_view=False):
        ws = self.operator.ws(workspace)
        record, directory, _ = self._inspect(ws, identifier(key))
        allowed = {row["path"]: row for row in self._files(record, directory).values()}
        if name not in allowed:
            raise self.Fault("SCIENTIFIC_REPORT_MEMBER", "Choose a file in this saved report.", 404)
        item = allowed[name]
        path = relative_file(directory, name)
        result = (self.operator._ticket(workspace, path, item, name), path)
        if with_view:
            view = "report" if name == record["files"].get("report_html", {}).get("path") else None
            return (*result, view)
        return result

    def export(self, workspace, key):
        result = retained_editions.export(self.operator.ws(workspace), identifier(key))
        item = result["file"]
        return {"scientific_report_edition_id": result["scientific_report_edition_id"],
                "state": result["state"],
                "download": self.operator._ticket(
                    workspace, Path(result["directory"]) / item["path"], item,
                    result["title"] + " — complete report files")}


    def briefing_catalog(self, workspace, source_edition_id):
        root = self.operator.ws(workspace).root / scientific_briefing.KIND
        rows = []
        for path in sorted(root.glob("*/briefing.json")):
            record = read_json(path)
            if record.get("source_edition_id") == source_edition_id:
                rows.append({name: record[name] for name in
                    ("id", "title", "source_edition_id", "page_count", "source_count", "figure_count")})
        return rows

    def briefing_preview(self, workspace, payload):
        result = scientific_briefing.preview(self.operator.ws(workspace), identifier(payload.get("id")))
        return {"workspace_key": workspace, **result}

    def briefing_prepare(self, workspace, payload):
        ws = self.operator.ws(workspace)
        record = scientific_briefing.create(ws, identifier(payload.get("id")),
                                            expected_id=payload.get("preview_id"))
        scientific_briefing.export(ws, record["id"])
        return {"scientific_report_edition_id": record["source_edition_id"],
                "scientific_briefing_id": record["id"], "state": "complete",
                "title": record["title"], "page_count": record["page_count"]}

    def briefing_detail(self, workspace, key):
        ws = self.operator.ws(workspace)
        record, directory, members = scientific_briefing.members(ws, identifier(key))
        def url(name):
            return "/api/file/scientific-briefings/" + "/".join(
                quote(str(part), safe="") for part in (workspace, key)) + "/" + quote(name, safe="/")
        files = [{field: item[field] for field in ("path", "bytes", "sha256")}
                 for item in members.values()]
        for row in files:
            row["url"] = url(row["path"])
        receipt = directory / "archive.json"
        archive = None
        if receipt.exists():
            descriptor = read_json(receipt)["file"]
            path = verify_file(directory, descriptor)
            archive = self.operator._ticket(workspace, path, descriptor, "Complete scientific briefing ZIP")
        generated = [self.operator._ticket(workspace, verify_file(directory, row), row, role)
                     for role, row in record["files"].items()]
        return {"workspace_key": workspace, "briefing": record, "files": files,
                "viewer_url": url(record["files"]["html"]["path"]), "archive": archive,
                "_downloads": ([archive] if archive else []) + generated}

    def briefing_member(self, workspace, key, name, *, with_view=False):
        ws = self.operator.ws(workspace)
        record, directory, members = scientific_briefing.members(ws, identifier(key))
        if name not in members:
            raise self.Fault("SCIENTIFIC_BRIEFING_MEMBER", "Choose a retained briefing or original report file.", 404)
        descriptor = members[name]
        path = Path(descriptor["source"])
        result = (self.operator._ticket(workspace, path, descriptor, name), path)
        if with_view:
            view = None
            if name == record["original_files"].get("report_html", {}).get("path"):
                view = "report"
            elif (name == record["files"].get("html", {}).get("path")
                  and self._current_briefing_document(record, members, name)):
                view = "briefing"
            return (*result, view)
        return result

    @staticmethod
    def _current_briefing_document(record, members, name):
        """Recognize only the exact installed, escaped interactive template.

        The original members() call has verified the retained Workspace/report
        binding and every declared member. Recheck the bytes actually used for
        reconstruction so script provenance follows installed source, not merely
        an archive's own manifest.
        """
        from model import client_briefing

        def original_bytes(member):
            item = members[member]
            body = Path(item["source"]).read_bytes()
            if len(body) != item["bytes"] or hashlib.sha256(body).hexdigest() != item["sha256"]:
                raise ValueError("The retained scientific briefing member changed")
            return body

        try:
            model_body = original_bytes(record["files"]["model"]["path"])
            report = json.loads(model_body)
            if report.get("schema") != scientific_briefing.SCHEMA:
                return False
            figures = {
                figure["path"]: "data:image/svg+xml;base64," + base64.b64encode(
                    original_bytes(figure["path"])).decode("ascii")
                for section in report["sections"] for figure in section.get("figures", [])
            }
            document, _ = client_briefing.render(
                report, report_href=record["original_files"]["report_html"]["path"],
                model_href=record["files"]["model"]["path"],
                report_model_bytes=model_body, figure_images=figures)
            return document.encode("utf-8") == original_bytes(name)
        except (OSError, ValueError, TypeError, KeyError, UnicodeError):
            # Older producer editions keep the original isolated reader and
            # complete offline package, including their original script bodies.
            return False

    def review_preview(self, workspace, payload):
        result = scientific_report_review.preview_review(
            self.operator.ws(workspace), payload.get("edition_id"),
            payload.get("review_selection"))
        return {**result, "workspace_key": workspace}

    def review(self, task):
        payload = task["payload"]
        return scientific_report_review.create_review(
            self.operator.ws(task["workspace"]), payload.get("edition_id"),
            payload.get("review_selection"),
            expected_operation_id=payload.get("expected_operation_id"),
            created_at=task["created_at"])

    def read(self, workspace, operation, payload):
        if operation == "scientific-capture":
            return self.capture_preview(workspace, payload)
        if operation == "scientific-review-preview":
            return self.review_preview(workspace, payload)
        if operation == "scientific-briefing-preview":
            return self.briefing_preview(workspace, payload)
        if operation == "scientific-briefing":
            return self.briefing_detail(workspace, payload.get("id"))
        if operation == "scientific-catalog":
            return self.catalog(workspace)
        if operation == "scientific-preview":
            return self.preview(workspace, payload)
        if operation == "scientific-edition":
            return self.detail(workspace, payload.get("id"))
        raise self.Fault("SCIENTIFIC_REPORT_READ", "Choose a saved scientific report operation.", 404)

    def invoke(self, task):
        if task["action"] == "source-reports.adopt":
            return self.adopt(task["workspace"], task["payload"])
        if task["action"] == "source-reports.review":
            return self.review(task)
        if task["action"] == "source-reports.briefing":
            return self.briefing_prepare(task["workspace"], task["payload"])
        if task["action"] == "source-reports.render":
            return self.render(task["workspace"], task["payload"])
        if task["action"] == "source-reports.export":
            return self.export(task["workspace"], task["payload"].get("id"))
        raise self.Fault("SCIENTIFIC_REPORT_ACTION", "Choose a scientific report task.")

    def state(self, workspace):
        return {"scientific_report_editions": self.saved(workspace)}

    def verify_workspace(self, workspace):
        rows = []
        for path in sorted((workspace.root / KIND).glob("*/edition.json")):
            record, _, _ = self._inspect(workspace, path.parent.name)
            rows.append({"id": record["id"], "source_count": record["source_count"]})
        briefings = []
        for path in sorted((workspace.root / scientific_briefing.KIND).glob("*/briefing.json")):
            record, _ = scientific_briefing.inspect(workspace, path.parent.name)
            briefings.append({"id": record["id"], "source_edition_id": record["source_edition_id"]})
        return {"scientific_report_editions": rows, "verified_count": len(rows),
                "scientific_briefings": briefings}

    def decorate_task(self, task):
        if task["state"] != "complete" or task["action"] not in ACTIONS:
            return task
        result = task.get("result") or {}
        if task["action"] == "source-reports.review":
            return {**task, "_review": {
                "kind": "review", "review_id": result["review_id"],
                "scientific_report_edition_id": result["scientific_report_edition_id"],
                "title": result["title"], "artifact_count": result["artifact_count"]}}
        key = result.get("scientific_report_edition_id")
        if not key:
            return task
        if task["action"] == "source-reports.briefing":
            downloads = self.briefing_detail(task["workspace"], result["scientific_briefing_id"])["_downloads"]
        elif task["action"] == "source-reports.export":
            completed = self.detail(task["workspace"], key)
            downloads = [completed["archive"]] if completed["archive"] else []
        else:
            downloads = self.detail(task["workspace"], key)["_downloads"]
        return {**task, "_downloads": downloads}

import {attachScientificSourceReader} from './scientific_source_reader.mjs';
/** Prepare ordered scientific reports through the original retained task queue. */
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=row=>JSON.stringify([row.source_collection_id,row.source_id]);
const choice=row=>({source_collection_id:row.source_collection_id,source_id:row.source_id});
const size=n=>Number(n).toLocaleString()+' B';
const link=(url,label)=>'<a href="'+esc(url)+(url.includes('?')?'&':'?')+'download=1" download>'+esc(label)+'</a>';

export function orderedReportSources(catalog, selected) {
  if(!Array.isArray(selected))throw Error('Choose an ordered list of scientific sources.');
  const byKey=new Map(catalog.map(row=>[key(row),row])),seen=new Set();
  return selected.map(row=>{
    const id=key(row);
    if(seen.has(id))throw Error('Choose each original report source once.');
    seen.add(id);
    if(!byKey.has(id))throw Error('A selected report source is no longer in this Workspace. Refresh its source edition.');
    return byKey.get(id);
  });
}

export const SCIENTIFIC_REPORT_SOURCE_SELECTION = 'replace-v1';

export function attachScientificReportEditions(host) {
  let panel=null,workspace=null,generation=0,revision=0,detailGeneration=0,active=false;
  let sources=[],editions=[],selected=[],title='',contact={name:'',organization:'',email:''};
  let preview=null,opened=null,busy=false,error='',pending=null,storageIssue='';
  let briefingPreview=null,briefingOpened=null;
  let capturedReports=[],captureIssues=[],capturePreview=null,captureGeneration=0;
  const briefingFrames=new Map(),reportFrames=new Map();
  let sourceIntent=0,catalogGeneration=0,catalogRead=null;
  const sourceReader=attachScientificSourceReader({...host,compose:value=>openForSources(value),
    returnToSelection:()=>panel?.querySelector('[data-scientific-report-main]')?.scrollIntoView({block:'start'})});
  const valid=(ws,turn)=>workspace===ws&&host.getWorkspace()===ws&&generation===turn;
  const request=(path,values={})=>host.api(host.endpoint(path,values));
  const payload=()=>({sources:selected.map(choice),...(title.trim()?{title:title.trim()}:{}),contact:{...contact}});
  function changed(){revision++;preview=null;saveDraft();}
  function saveDraft(){
    try{sessionStorage.setItem('scientific-report-draft:'+workspace,JSON.stringify({selected,title,contact,pending}));storageIssue='';}
    catch{storageIssue='Browser storage is unavailable. Keep this report desk open until its original request is recovered.';}
  }
  function restoreDraft(){
    try{
      const saved=JSON.parse(sessionStorage.getItem('scientific-report-draft:'+workspace)||'null');
      if(saved&&Array.isArray(saved.selected)){selected=saved.selected.map(choice);title=typeof saved.title==='string'?saved.title:'';
        contact={name:String(saved.contact?.name??''),organization:String(saved.contact?.organization??''),email:String(saved.contact?.email??'')};
        const retained=saved.pending;
        if(retained&&typeof retained.id==='string'&&retained.id&&
            ['source-reports.render','source-reports.export','source-reports.briefing','source-reports.adopt'].includes(retained.action)&&
            retained.body&&typeof retained.body==='object'&&!Array.isArray(retained.body)&&
            retained.key===JSON.stringify([workspace,retained.action,retained.body])){
          pending=retained;
        }
      }
    }catch{}
  }
  function ensure(container){
    if(!panel){
      panel=document.createElement('section');panel.className='scientific-report-editions';
      panel.setAttribute('aria-label','Prepare and reopen scientific reports');
      panel.innerHTML='<div data-scientific-report-main></div><section data-scientific-report-detail hidden></section><section data-scientific-report-document-host class="source-report-frame-shell" hidden></section><section data-scientific-report-briefing-host hidden></section><section data-scientific-report-files hidden></section>';
      panel.addEventListener('click',event=>{
        const button=event.target.closest('[data-scientific-report-action]');
        if(!button||!panel.contains(button))return;
        event.preventDefault();event.stopPropagation();
        const ws=workspace,turn=generation;
        dispatch(button).catch(reason=>{if(valid(ws,turn)){error=reason.message||String(reason);render();}});
      });
      panel.addEventListener('input',event=>{
        const field=event.target.dataset.scientificReportField;
        if(!field)return;
        if(busy||pending){error='Recover the original report request before editing its selection.';render();return;}
        if(field==='title')title=event.target.value;
        else contact[field]=event.target.value;
        changed();
        panel.querySelector('[data-scientific-report-preview]').textContent='Preview the current selection before preparing the report.';
        const button=panel.querySelector('[data-scientific-report-action="render"]');if(button)button.disabled=true;
      });
    }
    if(panel.parentNode!==container)container.append(panel);
    panel.hidden=false;
    sourceReader.mount(panel);
  }
  function sourceActions(row,reportId=''){
    const native=row.native_study,available=typeof host.openGISStudy==='function'&&host.hasView?.('gis-projects');
    const attributes=' data-collection="'+esc(row.source_collection_id)+'" data-source="'+esc(row.source_id)+'"'+
      (reportId?' data-report="'+esc(reportId)+'"':'');
