  async function showRetainedTask(){
    const original=pending,ws=workspace,turn=generation;
    if(!original?.task_id)throw Error('The original report task has not returned its ID yet.');
    await host.refresh({force:true});
    if(!valid(ws,turn)||pending!==original)return;
    await host.showTask(original.task_id);
    if(!valid(ws,turn)||pending!==original)return;
    pending=null;saveDraft();await refresh();
  }
  async function submit(action,body){
    if(busy)return;
    const ws=workspace,turn=generation;
    const requestKey=JSON.stringify([ws,action,body]);
    if(pending&&pending.key!==requestKey)
      throw Error('Recover the original report request before starting another.');
    if(!pending)pending={key:requestKey,id:crypto.randomUUID(),action,body:JSON.parse(JSON.stringify(body))};
    const original=pending;
    saveDraft();busy=true;error='';render();
    try{
      if(original.task_id){await showRetainedTask();return;}
      const requestBody={workspace:ws,action:original.action,payload:original.body,operation_id:original.id};
      const response=await host.api('/api/actions',{method:'POST',body:requestBody});
      if(!valid(ws,turn)||pending!==original)return;
      const task=response.task||response;
      if((task.workspace&&task.workspace!==ws)||(response.workspace&&response.workspace!==ws))throw Error('The retained report task belongs to another Workspace.');
      if(typeof task.id!=='string'||!task.id)throw Error('The original request is retained. Recover its native task response.');
      original.task_id=task.id;saveDraft();
      await showRetainedTask();
    }finally{if(valid(ws,turn)){busy=false;saveDraft();render();}}
  }
  async function recover(){
    if(busy||!pending)return;
    return submit(pending.action,pending.body);
  }
  async function dispatch(button){
    const action=button.dataset.scientificReportAction;
    if(action==='recover')return recover();
    if(action==='inspect-available'){
      detailGeneration++;
      const value=panel.querySelector('[data-scientific-report-source]').value;
      return inspectSource(sources.find(item=>key(item)===value));
    }
    if(['add','up','down','remove','preview','render','revise','export','briefing-preview','briefing-prepare','capture-preview','capture-adopt'].includes(action)&&(busy||pending))
      throw Error('Recover the original report request before changing its selection or starting another.');
    if(action==='refresh'){await refresh();if(opened)await open(opened.edition.id);return;}
    if(action==='capture-preview')return previewCapture(button.dataset.id);
    if(action==='capture-close'){captureGeneration++;capturePreview=null;render();return;}
    if(action==='capture-adopt'){
      if(!capturePreview)throw Error('Review the completed report and its original source identity first.');
      return submit('source-reports.adopt',{capture_id:capturePreview.capture_id,
        capture_sha256:capturePreview.capture_sha256,edition_id:capturePreview.edition_id});
    }
    if(action==='add'){
      const value=panel.querySelector('[data-scientific-report-source]').value;
      const row=sources.find(item=>key(item)===value);
      if(!row)throw Error('Choose a retained scientific report source.');
      selected.push(choice(row));orderedReportSources(sources,selected);changed();render();return;
    }
    if(['up','down','remove'].includes(action)){
      const index=Number(button.dataset.index);
      if(!Number.isInteger(index)||index<0||index>=selected.length)throw Error('Choose a selected study.');
      if(action==='remove')selected.splice(index,1);
      else {const next=index+(action==='up'?-1:1);if(next<0||next>=selected.length)return;[selected[index],selected[next]]=[selected[next],selected[index]];}
      changed();render();return;
    }
    if(action==='briefing-preview')return previewBriefing();
    if(action==='briefing-open')return openBriefing(button.dataset.id);
    if(action==='briefing-prepare'){
      if(!opened||!briefingPreview||briefingPreview.source_edition_id!==opened.edition.id)
        throw Error('Preview this exact saved report before preparing its discussion package.');
      return submit('source-reports.briefing',{id:opened.edition.id,preview_id:briefingPreview.id});
    }
    if(action==='preview')return preparePreview();
    if(action==='render'){
      if(!preview)throw Error('Preview the current ordered selection first.');
      if(preview.existing)return open(preview.id);
      return submit('source-reports.render',{...payload(),preview_id:preview.id});
    }
    if(action==='open')return open(button.dataset.id);
    if(action==='close'){detailGeneration++;opened=null;briefingPreview=null;briefingOpened=null;render();return;}
    if(action==='revise'&&opened){
      const identity=opened.edition.render_identity,selection=identity.selection;
      selected=(selection.observed_context_sources||[selection.source_roles.OBSERVED_CONTEXT]).map(choice);
      title=opened.edition.title;contact={...identity.contact};changed();render();
      panel.scrollIntoView({block:'start'});return;
    }
    if(action==='export'&&opened)return submit('source-reports.export',{id:opened.edition.id});
    if(action==='transfer'&&opened){
      if(typeof host.openStudy!=='function')throw Error('Open Study transfer in this application to transfer the saved report.');
      const ws=workspace,turn=generation,ticket=++detailGeneration,id=opened.edition.id;
      const result=await request('/api/source-reports/scientific-edition',{id});
      if(!active||!valid(ws,turn)||ticket!==detailGeneration||opened?.edition.id!==id)return;
      if(result.workspace_key!==ws||result.edition?.id!==id||result.edition.state!=='complete')
        throw Error('The completed report differs from the selected original edition.');
      return host.openStudy({workspace_key:ws,roots:[{kind:'scientific-report-editions',id,
        title:result.edition.title,state:'complete'}]});
    }
    if(action==='review'&&opened){
      if(typeof host.prepareCustomerReview!=='function')throw Error('Open the complete application to prepare a customer review.');
      const original=opened,ws=workspace,turn=generation,ticket=detailGeneration;
      return host.prepareCustomerReview({workspace_key:ws,edition_id:original.edition.id,
        isCurrent:()=>valid(ws,turn)&&active&&opened===original&&detailGeneration===ticket});
    }
    if(action==='source'||action==='gis'||action==='read-source'){
      const pair={source_collection_id:button.dataset.collection,source_id:button.dataset.source};
      const id=button.dataset.report||null,ws=workspace,turn=generation,ticket=++detailGeneration;
      if(action==='gis'&&(busy||pending))throw Error('Recover the original report request before opening another workflow.');
      let row;
      if(id){
        if(opened?.edition.id!==id)throw Error('Open the selected saved report first.');
        const result=await request('/api/source-reports/scientific-edition',{id});
        if(!active||!valid(ws,turn)||ticket!==detailGeneration||opened?.edition.id!==id)return;
        if(result.workspace_key!==ws||result.edition?.id!==id||result.edition.state!=='complete')
          throw Error('The saved report differs from the selected original edition.');
        row=result.edition.sources.find(item=>key(item)===key(pair));
        if(row)row={...row,native_study:(result.native_studies||[]).find(item=>key(item)===key(pair))};
      }else{
        const result=await request('/api/source-reports/scientific-catalog');
        if(!active||!valid(ws,turn)||ticket!==detailGeneration)return;
        if(result.workspace_key!==ws)throw Error('The source catalog belongs to another Workspace.');
        row=result.sources.find(item=>key(item)===key(pair));
      }
      if(!row)throw Error('Choose a source retained in the selected original report.');
      if(action==='read-source')return inspectSource(row);
      if(action==='source')return host.openItem('sources',pair.source_collection_id);
      if(!row.native_study?.local_project||typeof host.openGISStudy!=='function'||!host.hasView?.('gis-projects'))
        throw Error('Open this native study in its restored original project with the editable GIS desk.');
      return host.openGISStudy({workspace_key:ws,...pair,...(id?{scientific_report_id:id}:{})});
    }
    if(action==='backup')return host.openBackup();
  }
  async function mount(container,{loadCatalog=true}={}){
    const ws=host.getWorkspace();
    if(workspace!==ws){reset();workspace=ws;restoreDraft();}
    active=true;ensure(container);render();
    if(loadCatalog)await refresh();
  }
  async function openForStudy(value){
    if(!value||value.workspace_key!==host.getWorkspace()||value.workspace_key!==workspace)
      throw Error('Open the saved scientific report in its receiving Workspace.');
    if(typeof value.id!=='string'||!/^[0-9a-f]{64}$/.test(value.id))
      throw Error('Choose an exact saved scientific report edition.');
    if(!active||!panel)throw Error('Open Sources before reopening the saved report.');
    if(typeof value.isCurrent==='function'&&!value.isCurrent())return;
    return open(value.id,{isCurrent:value.isCurrent});
  }
  async function openForSources(value){
    if(!value||value.workspace_key!==host.getWorkspace()||value.workspace_key!==workspace)
      throw Error('Open the prepared report sources in their original Workspace.');
    if(!Array.isArray(value.sources)||!value.sources.length)
      throw Error('Choose one or more original prepared report sources.');
    const selectionMode=value.selection_mode??'append';
    if(!['append','replace'].includes(selectionMode))throw Error('Choose a supported scientific report source selection mode.');
    if(busy||pending)throw Error('Finish or recover the retained scientific report request before adding more sources.');
    const ws=workspace,turn=generation,version=revision,intent=++sourceIntent;
    const current=()=>active&&valid(ws,turn)&&intent===sourceIntent&&
      (typeof value.isCurrent!=='function'||value.isCurrent());
    if(!current())return null;
    const catalogue=await refresh();
    if(!current()||!catalogue)return null;
    if(busy||pending)throw Error('Finish or recover the retained scientific report request before adding more sources.');
    if(selectionMode==='replace'&&revision!==version)
      throw Error('The report draft changed before its prepared sources opened. Open the prepared selection again.');
    const incoming=orderedReportSources(catalogue.sources||[],value.sources).map(choice);
    if(selectionMode==='replace'){
      selected=incoming;
      title=typeof value.title==='string'?value.title:'';
    }else{
      const seen=new Set(selected.map(key));
      for(const row of incoming){if(!seen.has(key(row))){selected.push(row);seen.add(key(row));}}
      if(!title.trim()&&typeof value.title==='string')title=value.title;
    }
    changed();error='';render();
    panel.scrollIntoView({block:'start'});
    panel.querySelector('[data-scientific-report-action="preview"]').focus?.();
    return {workspace_key:ws,sources:selected.map(choice)};
  }
  function detach(){active=false;sourceIntent++;catalogGeneration++;catalogRead=null;detailGeneration++;captureGeneration++;sourceReader.detach();if(panel)panel.hidden=true;}
  function reset(){
    generation++;revision++;detailGeneration++;if(panel)panel.remove();
    briefingFrames.clear();reportFrames.clear();sourceReader.reset();sourceIntent++;catalogGeneration++;catalogRead=null;
    panel=null;workspace=null;sources=[];editions=[];selected=[];title='';
    capturedReports=[];captureIssues=[];capturePreview=null;captureGeneration++;
    contact={name:'',organization:'',email:''};
    preview=null;opened=null;briefingPreview=null;briefingOpened=null;busy=false;pending=null;error='';storageIssue='';active=false;
  }
  return {mount,detach,reset,refresh,openForSources,openForStudy};
}

/** Inspect original scientific source bytes inside the existing report composer. */
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const choice=value=>({source_collection_id:value.source_collection_id,source_id:value.source_id});
const key=value=>JSON.stringify([value.source_collection_id,value.source_id,value.body_sha256||'']);
const cell=value=>typeof value==='string'?value:JSON.stringify(value)??String(value);
const download=(file,label)=>'<a href="'+esc(file.url)+(file.url.includes('?')?'&':'?')+'download=1" download>'+esc(label)+'</a>';
const PAGE=50;

export function attachScientificSourceReader(host){
  let panel=null,workspace=null,active=false,generation=0,requestId=0,opened=null,error='',busy=false;
  let query='',pages=new Map(),documentPath=null,readingTitle='';
  const frames=new Map();
  const valid=(ws,turn)=>active&&workspace===ws&&host.getWorkspace()===ws&&generation===turn;
  function ensure(container){
    if(!panel){
      panel=document.createElement('section');panel.className='scientific-source-reader';panel.hidden=true;
      panel.setAttribute('aria-label','Read original scientific study');
      panel.innerHTML='<div data-source-reader-heading></div><div data-source-reader-status role="status"></div><div data-source-reader-controls></div><div data-source-reader-document></div><div data-source-reader-content></div><div data-source-reader-files></div>';
      panel.addEventListener('click',event=>{
        const button=event.target.closest('[data-source-reader-action]');
        if(!button||!panel.contains(button))return;
        event.preventDefault();event.stopPropagation();
        const ws=workspace,turn=generation;
        dispatch(button).catch(reason=>{if(valid(ws,turn)){error=reason.message||String(reason);status();}});
      });
      panel.addEventListener('input',event=>{
        if(event.target.matches('[data-source-reader-query]')){
          query=event.target.value;pages.clear();renderSections();
        }
      });
      panel.addEventListener('change',event=>{
        if(event.target.matches('[data-source-reader-document-choice]')){
          documentPath=event.target.value||null;renderDocument();
        }
      });
    }
    if(panel.parentNode!==container)container.append(panel);
  }
  function status(){if(panel)panel.querySelector('[data-source-reader-status]').textContent=error||(busy?'Reading complete original source: '+readingTitle+'…':'');}
  async function open(source,{isCurrent}={}){
    if(!active||!panel)throw Error('Open Sources before reading its original scientific study.');
    if(!source||typeof source.source_collection_id!=='string'||typeof source.source_id!=='string')
      throw Error('Choose an exact retained scientific source.');
    const ws=workspace,turn=generation,ticket=++requestId;
    const current=()=>valid(ws,turn)&&ticket===requestId&&(typeof isCurrent!=='function'||isCurrent());
    busy=true;error='';readingTitle=String(source.title||source.source_id);panel.hidden=false;
    if(!opened)panel.querySelector('[data-source-reader-heading]').innerHTML=
      '<div class="source-reports-heading"><div><h3>Read original scientific study</h3><p>'+esc(readingTitle)+
      '</p></div><button type="button" data-source-reader-action="close">Return to report selection</button></div>';
    status();
    let result;
    try{result=await host.api(host.endpoint('/api/source-reports/scientific-source',{
      ...choice(source),...(source.body_sha256?{body_sha256:source.body_sha256}:{})}));}
    catch(reason){if(!current())return null;busy=false;error=reason.message||String(reason);status();throw reason;}
    if(!current())return null;
    if(result.schema!=='upstate.scientific-source-reader/v1'||result.workspace_key!==ws||
       result.source?.source_collection_id!==source.source_collection_id||result.source?.source_id!==source.source_id||
       (source.body_sha256&&result.source.body_sha256!==source.body_sha256)||
       !Array.isArray(result.files)||!Array.isArray(result.recipe?.sections)){
      busy=false;error='The original source reader returned another retained edition.';status();throw Error(error);
    }
    const same=opened&&key(opened.source)===key(result.source);
    opened=result;busy=false;error='';
    if(!same){query='';pages.clear();documentPath=null;}
    render();panel.scrollIntoView({block:'start'});panel.querySelector('[data-source-reader-action="close"]').focus?.();
    return result;
  }
  function render(){
    if(!panel||!opened)return;
    const source=opened.source,cohort=source.metadata?.source_kind==='upstate.observation-comparability/v1';
    panel.hidden=false;status();
    panel.querySelector('[data-source-reader-heading]').innerHTML='<div class="source-reports-heading"><div><h3>'+esc(source.title)+'</h3><p>'+
      esc(source.vintage)+' · '+esc(source.collection_title)+'</p></div><button type="button" data-source-reader-action="close">Return to report selection</button></div>'+
      '<p>These are the original study’s retained sections and files. Reading them keeps the report’s current title, contact and ordered selection.</p>'+
      '<details><summary>Exact original source identity</summary><dl><dt>Collection</dt><dd><code>'+esc(source.source_collection_id)+'</code></dd><dt>Document</dt><dd><code>'+
      esc(source.source_id)+'</code></dd><dt>Source SHA256</dt><dd><code>'+esc(source.body_sha256)+'</code></dd><dt>Publisher / source</dt><dd>'+
      esc(source.uri)+'</dd></dl></details>';
    const documents=opened.files.filter(file=>file.kind==='html'||file.kind==='svg');
    panel.querySelector('[data-source-reader-controls]').innerHTML='<div class="inline-actions">'+
      '<button type="button" data-source-reader-action="append">Add this study to current report</button>'+
      '<button type="button" data-source-reader-action="replace">Prepare report from this study only</button>'+
      (cohort&&typeof host.openExtension==='function'?'<button type="button" data-source-reader-action="cohort">Explore original cohort and periods</button>':'')+
      download(opened.original_manifest,'Download original manifest')+'</div>'+
      (documents.length?'<label>Original document or figure<select data-source-reader-document-choice><option value="">Read retained source tables below</option>'+
      documents.map(file=>'<option value="'+esc(file.path)+'"'+(documentPath===file.path?' selected':'')+'>'+esc(file.path)+'</option>').join('')+'</select></label>':'')+
      '<label>Find text in original source tables<input data-source-reader-query value="'+esc(query)+'" placeholder="Activity, result, station, method or original value"></label>'+
      '<p class="note">Table search changes only this view. Every original row and companion file remains in the downloads below.</p>';
    renderDocument();renderSections();
    panel.querySelector('[data-source-reader-files]').innerHTML='<details><summary>All '+opened.files.length+' original files and downloads</summary>'+
      '<div class="table-scroll" tabindex="0" role="region" aria-label="Complete original scientific source files"><table><thead><tr><th>Original path</th><th>Bytes / SHA256</th><th>File</th></tr></thead><tbody>'+
      opened.files.map(file=>'<tr><td><code>'+esc(file.path)+'</code></td><td>'+esc(file.bytes)+'<small class="mono">'+esc(file.sha256)+'</small></td><td>'+download(file,'Download original')+'</td></tr>').join('')+
      '</tbody></table></div></details>';
  }
  function renderDocument(){
    const target=panel.querySelector('[data-source-reader-document]');
    const file=opened?.files.find(row=>row.path===documentPath&&(row.kind==='html'||row.kind==='svg'));
    for(const frame of target.children)frame.hidden=true;
    if(!file)return;
    const frameKey=key(opened.source)+':'+file.path+':'+file.sha256;
    let frame=frames.get(frameKey);
    if(!frame){
      frame=document.createElement('iframe');frame.title=opened.source.title+' — '+file.path;
      frame.setAttribute('sandbox','allow-scripts allow-downloads allow-modals allow-popups allow-popups-to-escape-sandbox');
      frame.referrerPolicy='no-referrer';frame.src=file.url;frames.set(frameKey,frame);
    }
    if(frame.parentNode!==target)target.append(frame);
    frame.hidden=false;
  }
  function renderSections(){
    if(!opened||!panel)return;
    const members=new Map(opened.files.map(file=>[file.path,file])),words=query.toLocaleLowerCase().trim().split(/\s+/).filter(Boolean);
    panel.querySelector('[data-source-reader-content]').innerHTML=opened.recipe.sections.map(([heading,blocks],section)=>
      '<section><h4>'+esc(heading)+'</h4>'+blocks.map((block,index)=>{
        if(typeof block==='string')return '<p class="source-original-cell">'+esc(block)+'</p>';
        if(block.kind==='links')return '<ul>'+(block.items||[]).map(item=>{
          const file=members.get(item.path);return '<li>'+(file?download(file,item.title||item.path):esc(item.title||item.path)+' — original member is unavailable')+'</li>';
        }).join('')+'</ul>';
        if(block.kind!=='table')return '';
        const tableKey=section+':'+index,all=block.rows||[],filtered=all.filter(row=>words.every(word=>row.some(value=>cell(value).toLocaleLowerCase().includes(word))));
        const last=Math.max(0,Math.ceil(filtered.length/PAGE)-1),page=Math.min(pages.get(tableKey)||0,last);pages.set(tableKey,page);
        const rows=filtered.slice(page*PAGE,(page+1)*PAGE);
        return '<section class="scientific-source-table">'+(block.caption?'<p>'+esc(block.caption)+'</p>':'')+
          '<p>'+filtered.length+' of '+all.length+' original rows'+(filtered.length?' · showing '+(page*PAGE+1)+'–'+(page*PAGE+rows.length):'')+'</p>'+
          '<div class="table-scroll" tabindex="0" role="region" aria-label="'+esc(heading+' original table '+(index+1))+'"><table><thead><tr>'+
          block.columns.map(name=>'<th>'+esc(cell(name))+'</th>').join('')+'</tr></thead><tbody>'+
          rows.map(row=>'<tr>'+row.map(value=>'<td class="source-original-cell">'+esc(cell(value))+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>'+
          (last?'<div class="inline-actions"><button type="button" data-source-reader-action="page" data-table="'+tableKey+'" data-page="'+(page-1)+'"'+(!page?' disabled':'')+'>Previous rows</button>'+
          '<span>Page '+(page+1)+' of '+(last+1)+'</span><button type="button" data-source-reader-action="page" data-table="'+tableKey+'" data-page="'+(page+1)+'"'+(page===last?' disabled':'')+'>Next rows</button></div>':'')+'</section>';
      }).join('')+'</section>').join('');
  }
  async function dispatch(button){
    const action=button.dataset.sourceReaderAction;
    if(action==='close'){requestId++;busy=false;panel.hidden=true;host.returnToSelection?.();return;}
    if(!opened||busy)throw Error('Finish reading the selected original source first.');
    if(action==='page'){pages.set(button.dataset.table,Math.max(0,Number(button.dataset.page)||0));renderSections();return;}
    const original=opened,ws=workspace,turn=generation,ticket=requestId;
    const isCurrent=()=>valid(ws,turn)&&opened===original&&ticket===requestId&&!panel.hidden;
    if(action==='append'||action==='replace'){
      await host.compose({workspace_key:ws,sources:[choice(original.source)],selection_mode:action,
        title:original.source.title,isCurrent});
      return;
    }
    if(action==='cohort'){
      if(!isCurrent())return;
      return host.openExtension('observation-comparability','openSource',{workspace_key:ws,
        source:{kind:'retained',...choice(original.source),source_sha256:original.source.body_sha256}});
    }
  }
  function mount(container){
    const ws=host.getWorkspace();
    if(workspace!==ws){reset();workspace=ws;}
    active=true;ensure(container);
  }
  function detach(){active=false;requestId++;busy=false;if(panel)panel.hidden=true;}
  function reset(){detach();generation++;frames.clear();panel?.remove();panel=null;workspace=null;opened=null;error='';query='';pages.clear();documentPath=null;readingTitle='';}
  return {mount,open,detach,reset};
}

"""Discover and preview included source archives through the original operator.

Discovery reads only bounded artifact inventories and file metadata. Explicit
preview uses Operator.receive_upload and Operator.preview_source; those original
paths own ZIP validation, source selection and retained upload identity.
"""
from __future__ import annotations

import hashlib
import json
import os
from pathlib import Path, PurePosixPath
import re
from urllib.parse import quote
import zipfile

from model.common import digest

INVENTORY_LIMIT = 4 * 1024 * 1024
MEMBER_LIMIT = 20000
BUNDLED_SOURCE_ARCHIVE_INVENTORIES = (
    "results/native-assessment-annual-yields-20261013/artifacts.json",
)


def _name(value):
    if (not isinstance(value, str) or not value or "\\" in value
            or re.search(r"[\x00-\x1f\x7f]", value)):
        raise ValueError("The archive inventory needs an original relative file name.")
    path = PurePosixPath(value)
    if (path.is_absolute() or path.as_posix() != value
            or any(part in ("", ".", "..") or ":" in part for part in value.split("/"))):
        raise ValueError("Archive and manifest paths must stay inside their original edition.")
    return value


def _identity(row):
    if (not isinstance(row, dict)
            or not isinstance(row.get("bytes"), int) or isinstance(row["bytes"], bool)
            or row["bytes"] < 0
            or not isinstance(row.get("sha256"), str)
            or not re.fullmatch(r"[0-9a-f]{64}", row["sha256"])):
        raise ValueError("The archive inventory needs each original byte count and SHA256.")
    return {"path": _name(row.get("path")), "bytes": row["bytes"], "sha256": row["sha256"]}


def _inventory(path):
    with path.open("rb") as stream:
        raw = stream.read(INVENTORY_LIMIT + 1)
    if len(raw) > INVENTORY_LIMIT:
        raise ValueError("The source archive inventory exceeds 4 MiB.")
    value = json.loads(raw)
    if not isinstance(value, dict) or value.get("schema") != "commons.artifacts/v1":
        raise ValueError("Choose a commons.artifacts/v1 source archive inventory.")
    return value, hashlib.sha256(raw).hexdigest()


class IncludedSourceArchives:
    def __init__(self, operator, fault, application, source_roots=()):
        self.operator, self.Fault = operator, fault
        self.application = Path(application).resolve()
        self.source_roots = tuple(source_roots)
        self.records = {}

    def _candidates(self):
        seen = set()
        for base, origin, configured in [
                (self.application, "Included with this application", False),
                *((Path(root).expanduser(), "Configured source", True) for root in self.source_roots)]:
            if base.is_file():
                paths = [base] if base.name == "artifacts.json" or base.name.endswith("-artifacts.json") else []
            else:
                paths = [base / name for name in BUNDLED_SOURCE_ARCHIVE_INVENTORIES]
                if configured and base.is_dir():
                    paths.extend(sorted(base.glob("*-artifacts.json")))
                    paths.append(base / "artifacts.json")
            for path in paths:
                resolved = path.resolve()
                if resolved in seen or not resolved.is_file():
                    continue
                # A configured inventory file explicitly selects its parent edition;
                # a configured directory cannot redirect discovery outside that root.
                root = base.parent.resolve() if base.is_file() else base.resolve()
                if not resolved.is_relative_to(root):
                    continue
                seen.add(resolved)
                yield resolved, origin

    def discover(self):
        records, editions, issues = {}, [], []
        for path, origin in self._candidates():
            try:
                value, inventory_sha = _inventory(path)
                if value.get("archive") is None:
                    continue
                archive = _identity(value["archive"])
                if PurePosixPath(archive["path"]).suffix.lower() != ".zip":
                    raise ValueError("Included source archives must be original ZIP files.")
                manifest_member = _name(value["archive"].get("manifest_member"))
                files = value.get("files")
                if not isinstance(files, list) or not files or len(files) > MEMBER_LIMIT:
                    raise ValueError("The archive inventory must list its original source members.")
                members = {}
                for item in files:
                    member = _identity(item)
                    prior = members.setdefault(member["path"], member)
                    if prior != member:
                        raise ValueError("The archive inventory repeats a member with a different identity.")
                if manifest_member not in members:
                    raise ValueError("The selected import manifest needs a byte-bound inventory entry.")
                root = path.parent.resolve()
                target = (root / archive["path"]).resolve()
                if not target.is_relative_to(root):
                    raise ValueError("The included archive resolves outside its selected source edition.")
                problems = []
                try:
                    if not target.is_file():
                        raise ValueError("The included ZIP is missing. Restore this complete source edition.")
                    if target.stat().st_size != archive["bytes"]:
                        raise ValueError("The installed ZIP size differs from its declared original.")
                    if archive["bytes"] > self.operator.upload_limit:
                        raise ValueError("This ZIP exceeds the operator's selected upload capacity.")
                except OSError as error:
                    problems.append({"member": archive["path"], "reason": str(error)})
                except ValueError as error:
                    problems.append({"member": archive["path"], "reason": str(error)})
                key = digest({"inventory": str(path), "sha256": inventory_sha,
                              "archive": archive, "manifest_member": manifest_member})
                title = value.get("title")
                if not isinstance(title, str) or not title.strip():
                    title = PurePosixPath(archive["path"]).name
                record = {
                    "archive_id": key, "inventory_path": str(path), "inventory_sha256": inventory_sha,
                    "archive_path": str(target), "archive": archive,
                    "manifest_member": manifest_member, "manifest": members[manifest_member],
                    "title": title,
                }
                records[key] = record
                editions.append({
                    "archive_id": key, "registered_id": None, "source_kind": "included_archive",
                    "manifest_sha256": members[manifest_member]["sha256"],
                    "manifest_name": manifest_member, "title": title, "origin": origin,
                    "archive_name": archive["path"], "archive_bytes": archive["bytes"],
                    "archive_sha256": archive["sha256"],
                    "inventory_name": path.name, "entry_count": None,
                    "member_count": len(members), "reports": [], "documents": [],
                    "source_ids": [item for item in (value.get("source_id"), value.get("interactive_source_id"))
                                   if isinstance(item, str) and item],
                    "regional_context": False, "vintages": [], "ready": not problems,
                    "problems": problems,
                })
            except (OSError, ValueError, TypeError, KeyError) as error:
                issues.append({"manifest": path.name, "reason": str(error)})
        self.records = records
        return editions, issues

    def preview(self, workspace, archive_id):
        if not isinstance(archive_id, str) or not re.fullmatch(r"[0-9a-f]{64}", archive_id):
            raise self.Fault("SOURCE_ARCHIVE_SELECTION", "Choose an included source archive.")
        record = self.records.get(archive_id)
        if record is None:
            raise self.Fault("SOURCE_ARCHIVE_SELECTION",
                             "Refresh the available editions and choose an included source archive.", 404)
        # Match the existing registered-source authorization for server-owned files.
        context = self.operator.team.current()
        if context:
            self.operator.team.require(context["principal"], administrator=True)
            if context["workspace"] != workspace:
                raise self.Fault("SOURCE_ARCHIVE_WORKSPACE", "Preview the archive in the selected Workspace.", 409)
        self.operator.ws(workspace)
        try:
            unused, current_sha = _inventory(Path(record["inventory_path"]))
            if current_sha != record["inventory_sha256"]:
                raise ValueError("The archive inventory changed. Refresh and select its current edition.")
            root = Path(record["inventory_path"]).parent.resolve()
            path = (root / record["archive"]["path"]).resolve(strict=True)
            if not path.is_relative_to(root) or str(path) != record["archive_path"]:
                raise ValueError("The included archive location changed. Refresh its source edition.")
            with path.open("rb") as stream:
                before = os.fstat(stream.fileno())
                if before.st_size != record["archive"]["bytes"]:
                    raise ValueError("The included ZIP size changed. Restore or refresh the source edition.")
                upload = self.operator.receive_upload(
                    stream, record["archive"]["bytes"], quote(path.name, safe=""), "application/zip")
                after = os.fstat(stream.fileno())
                if (before.st_size, before.st_mtime_ns, before.st_ino) != (
                        after.st_size, after.st_mtime_ns, after.st_ino):
                    raise ValueError("The included ZIP changed during preview. Refresh and try again.")
            if any(upload.get(key) != record["archive"][key] for key in ("bytes", "sha256")):
                raise ValueError("The included ZIP bytes differ from their declared original. Restore this edition.")
            preview = self.operator.preview_source({
