    if(selected&&rowKey(selected)===key){panel.querySelector('[data-source-report-detail]').scrollIntoView({block:'start'});return;}
    const workspace=host.getWorkspace(),ticket=generation,detailTicket=++detailGeneration;
    showError({message:'Opening retained report…'});
    const value=await request('/api/source-reports/detail',{collection_id:row.collection_id,entry_key:row.entry_key});
    if(!valid(workspace,ticket)||detailTicket!==detailGeneration)return;
    if(value.workspace_key!==workspace||rowKey(value.report)!==key)throw Error('The returned report differs from the selected source.');
    selected=value.report;selectedMember=null;renderDetail();renderCatalog();
    panel.querySelector('[data-source-report-detail]').scrollIntoView({block:'start'});
  }
  async function archive(button){
    if(!selected)return;
    const workspace=host.getWorkspace(),key=rowKey(selected),ticket=generation,detailTicket=detailGeneration;
    button.disabled=true;
    const status=panel.querySelector('[data-source-report-archive-status]');
    status.textContent='Preparing the report and its complete original source edition…';
    try{
      const result=await host.api(host.endpoint('/api/source-reports/archive'),{method:'POST',
        body:{collection_id:selected.collection_id,entry_key:selected.entry_key}});
      if(!valid(workspace,ticket)||detailTicket!==detailGeneration||!selected||rowKey(selected)!==key)return;
      if(result.workspace_key!==workspace||result.source_id!==selected.source_id)throw Error('The portable report belongs to another selection.');
      status.innerHTML=download(result.download.url,'Download complete report ZIP')+' · '+size(result.download.bytes)+
        ' · import manifest: <span class="mono">'+esc(result.manifest_member)+'</span>'+
        '<small class="mono">SHA256 '+esc(result.download.sha256)+'</small>';
      const link=status.querySelector('a');link.click();
    }catch(error){if(valid(workspace,ticket))status.textContent=error.message||String(error);}
    finally{if(button.isConnected)button.disabled=false;}
  }
  async function previewIncludedArchive(button){
    const row=editions.find(item=>item.archive_id===button.dataset.archiveId);
    if(!row?.ready||row.source_kind!=='included_archive')
      throw Error('Refresh and choose an available included source ZIP.');
    const workspace=host.getWorkspace(),ticket=generation,requestTicket=++archivePreviewGeneration;
    const current=()=>active&&valid(workspace,ticket)&&requestTicket===archivePreviewGeneration;
    button.disabled=true;
    showError({message:'Checking '+row.archive_name+' and its original import manifest…'});
    try{
      const result=await host.api(host.endpoint('/api/source-reports/included-archive-preview'),{
        method:'POST',body:{archive_id:row.archive_id},
      });
      if(!current())return;
      if(result.workspace_key!==workspace||result.archive_id!==row.archive_id||
        result.archive?.sha256!==row.archive_sha256||result.archive?.bytes!==row.archive_bytes||
        result.preview?.manifest_sha256!==row.manifest_sha256||
        result.preview?.manifest_member!==row.manifest_name)
        throw Error('The returned archive differs from the selected edition. Refresh its source metadata.');
      showError({message:'Original ZIP checked. Review the source entries in the import form.'});
      return host.openSourceImport({mode:'included',includedArchive:result});
    }catch(error){if(current())showError({message:'Included ZIP: '+(error.message||String(error))});}
    finally{if(button.isConnected)button.disabled=false;}
  }
  async function dispatch(button){
    const action=button.dataset.sourceReportAction;
    if(action==='preview-archive')return previewIncludedArchive(button);
    archivePreviewGeneration++;
    if(action==='refresh')return catalog(true);
    if(action==='preview-edition'){
      const row=editions.find(item=>item.registered_id===button.dataset.registeredId);
      if(!row?.ready)throw Error('Refresh and choose an available original source edition.');
      return host.openSourceImport({mode:'registered',registeredId:row.registered_id,
        registeredManifest:{id:row.registered_id,title:row.title,entries:row.entry_count}});
    }
    if(action==='edition-scientific'){
      const workspace=currentWorkspace,ticket=generation,collectionId=button.dataset.collectionId;
      const row=editions.find(item=>item.manifest_sha256===button.dataset.manifestSha&&
        (item.retained_collections||[]).some(collection=>collection.id===collectionId));
      const sources=(row?.retained_scientific_sources||[]).filter(source=>source.source_collection_id===collectionId);
      if(!row||!sources.length||!valid(workspace,ticket))
        throw Error('Refresh and choose an original retained scientific source edition.');
      return scientific.openForSources({workspace_key:workspace,sources,title:row.title,selection_mode:'append'});
    }
    if(action==='retained-edition')return host.openItem('sources',button.dataset.collectionId);
    if(action==='edition-archive')return archiveEdition(button);
    if(action==='edition-reimport'){
      const row=retainedEditions.find(value=>value.collection_id===button.dataset.collectionId);
      const result=editionDownloads.get(button.dataset.collectionId)?.result;
      if(!row||!result||result.original_manifest_sha256!==row.original_manifest_sha256)
        throw Error('Download and inspect the original source edition before reimporting it.');
      return host.openSourceImport({mode:'archive',manifestMember:result.manifest_member});
    }
    if(action==='retained-scientific'){
      const row=retainedEditions.find(value=>value.collection_id===button.dataset.collectionId);
      if(!row?.scientific_sources?.length)throw Error('Choose an original retained scientific source edition.');
      return scientific.openForSources({workspace_key:currentWorkspace,sources:row.scientific_sources,title:row.title,selection_mode:'append'});
    }
    if(action==='import')return host.openSourceImport({mode:'archive',manifestMember:'sources.json'});
    if(action==='regional')return host.navigate('watershed-context');
    if(action==='stations')return host.navigate('station-geography');
    if(action==='deliveries')return host.navigate('deliveries');
    if(action==='scientific'&&selected)return scientific.openForSources({workspace_key:currentWorkspace,sources:selected.scientific_reports,title:selected.title});
    if(action==='open')return open(button.dataset.reportKey);
    if(action==='close'){detailGeneration++;clearSelection();renderCatalog();return;}
    if(action==='edition'&&selected)return host.openItem('sources',selected.collection_id);
    if(action==='archive')return archive(button);
  }
  async function mount(content){
    const workspace=host.getWorkspace();
    if(currentWorkspace!==workspace){reset();currentWorkspace=workspace;}
    active=true;ensurePanel(content);renderRegional();
    await Promise.all([catalog(),scientific.mount(panel.querySelector('[data-scientific-reports]'))]);
  }
  function detach(){
    archivePreviewGeneration++;active=false;editionGeneration++;
    for(const [key,value] of editionDownloads)if(value.busy)editionDownloads.delete(key);
    scientific.detach();if(panel)panel.hidden=true;
  }
  function reset(){
    scientific.reset();
    generation++;detailGeneration++;archivePreviewGeneration++;editionGeneration++;editionDownloads.clear();retainedEditions=[];
    loading=null;currentCatalogKey=null;reports=[];editions=[];discoveryIssues=[];selected=null;selectedMember=null;query='';catalogError=null;
    if(panel){panel.remove();panel=null;}currentWorkspace=null;active=false;
  }
  function focus(){if(panel&&active){panel.scrollIntoView({block:'start'});panel.querySelector('[data-source-report-search]').focus();}}
  async function openForSources(value,content){
    if(value?.workspace_key!==host.getWorkspace())
      throw Error('Choose prepared sources from the current Workspace.');
    const navigationCurrent=()=>typeof value.isCurrent!=='function'||value.isCurrent();
    if(!navigationCurrent())return null;
    if(!active||!panel||currentWorkspace!==host.getWorkspace())await mount(content);
    if(!active||!navigationCurrent())return null;
    const workspace=host.getWorkspace(),ticket=generation;
    const current=()=>active&&valid(workspace,ticket)&&navigationCurrent();
    return scientific.openForSources({...value,isCurrent:current});
  }
  async function openForStudy(value,content){
    if(!value||value.workspace_key!==host.getWorkspace())
      throw Error('Open the saved scientific report in its receiving Workspace.');
    const navigationCurrent=()=>typeof value.isCurrent!=='function'||value.isCurrent();
    if(!navigationCurrent())return;
    const workspace=host.getWorkspace();
    if(currentWorkspace!==workspace){reset();currentWorkspace=workspace;}
    const ticket=generation;
    active=true;ensurePanel(content);renderRegional();renderCatalog();
    const current=()=>active&&valid(workspace,ticket)&&navigationCurrent();
    try{
      // A known edition opens independently of source discovery or a catalogue outage.
      await scientific.mount(panel.querySelector('[data-scientific-reports]'),{loadCatalog:false});
      if(!current())return;
      return await scientific.openForStudy({...value,isCurrent:current});
    }catch(error){if(!current())return;throw error;}
  }
  return {mount,detach,reset,focus,openForSources,openForStudy};
}

.source-reports-panel{margin-top:28px;border-top:1px solid #c4c4c4;padding-top:24px;color:#222}
.source-reports-panel[hidden]{display:none!important}
.source-reports-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:18px}
.source-reports-panel h2{font-size:1.2rem;margin:0 0 8px}
.source-reports-panel p{line-height:1.55}
.source-reports-panel small{display:block;line-height:1.45;margin-top:4px;color:#555}
.source-reports-panel td{vertical-align:top}
.source-reports-panel .inline-actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.source-reports-panel button,.source-reports-panel input,.source-reports-panel select{border:1px solid #777;border-radius:3px;background:#fff;color:#222;padding:8px 10px;font:inherit}
.source-reports-panel button{cursor:pointer}
.source-reports-panel button:disabled{opacity:.6;cursor:wait}
.source-reports-panel a{color:#222;text-decoration:underline}
.source-reports-panel button:focus-visible,.source-reports-panel input:focus-visible,.source-reports-panel select:focus-visible,.source-reports-panel a:focus-visible{outline:2px solid #222;outline-offset:3px}
.source-reports-search,.source-reports-document{display:flex;flex-direction:column;gap:6px;margin:18px 0}
.source-reports-search input{max-width:600px}
.source-reports-panel [data-source-report-status]{margin:10px 0;color:#555}
.source-reports-panel [data-source-report-detail]{margin-top:26px;padding-top:22px;border-top:2px solid #555;scroll-margin-top:18px}
.source-reports-panel details{margin:16px 0;padding:12px;border:1px solid #ccc}
.source-reports-panel summary{cursor:pointer;font-weight:600}
.source-reports-panel pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.85rem}
.source-reports-panel .mono{font-family:monospace;overflow-wrap:anywhere}
.source-report-frame-shell{border:1px solid #aaa;background:#fff}
.source-report-frame-shell iframe{width:100%;height:75vh;min-height:520px;display:block;border:0;background:#fff}
.source-reports-panel [data-source-report-archive-status] small{display:block}
@media(max-width:700px){.source-reports-heading{display:block}.source-reports-heading .inline-actions{margin-top:12px}.source-report-frame-shell iframe{min-height:420px;height:70vh}}
@media print{.source-reports-panel{display:none}}

.source-report-editions { margin-block: 1.25rem 2rem; padding-block: 1rem; border-top: 1px solid #aaa; border-bottom: 1px solid #aaa; }
.source-report-editions h3 { margin: 0 0 .5rem; }
.source-report-editions td { vertical-align: top; }
.source-report-editions td:last-child { min-width: 10rem; }
.source-report-editions ul { margin: .5rem 0; padding-left: 1.25rem; }
.source-report-editions li + li { margin-top: .4rem; }
.source-report-editions .inline-actions { align-items: flex-start; flex-direction: column; }

.scientific-report-editions{margin-top:2rem;padding-top:1.5rem;border-top:2px solid #555}
.scientific-report-fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem}
.scientific-report-fields label{display:flex;flex-direction:column;gap:.4rem}
.scientific-report-fields input{width:100%;box-sizing:border-box}
.scientific-report-order{padding-left:1.5rem}
.scientific-report-order li{padding:.8rem .4rem;border-bottom:1px solid #ccc}
.scientific-report-order .inline-actions{margin-top:.5rem}
.scientific-report-preview{padding:1rem;margin:1rem 0;border:1px solid #aaa;background:#f6f6f6}
.scientific-report-editions [data-scientific-report-detail]{margin-top:1.5rem;padding-top:1rem;border-top:2px solid #555}
@media(max-width:700px){.scientific-report-fields{grid-template-columns:1fr}.scientific-report-order .inline-actions{gap:.5rem}}

/* Read original study members without replacing the report draft or its frames. */
.scientific-source-reader{margin-block:1.5rem;padding:1rem;border:1px solid var(--border,#c9cdd1);background:var(--panel,#fff)}
.scientific-source-reader label{display:block;margin-block:1rem}
.scientific-source-reader input,.scientific-source-reader select{display:block;width:100%;max-width:64rem;margin-top:.4rem}
.scientific-source-reader code{overflow-wrap:anywhere}
.scientific-source-reader .source-original-cell{white-space:pre-wrap;overflow-wrap:anywhere}
.scientific-source-reader .scientific-source-table{margin-block:1rem}
.scientific-source-reader .table-scroll{max-height:36rem;overflow:auto}
.scientific-source-reader .table-scroll:focus{outline:2px solid currentColor;outline-offset:2px}
.scientific-source-reader [data-source-reader-status]:not(:empty){padding-block:.75rem}
.scientific-source-reader [data-source-reader-document]>iframe{width:100%;height:70vh;min-height:24rem;border:1px solid var(--border,#c9cdd1)}
.scientific-source-reader [data-source-reader-document]>iframe[hidden],.source-report-frame-shell>iframe[hidden]{display:none}
@media(max-width:640px){.scientific-source-reader{padding:.65rem}.scientific-source-reader .inline-actions{display:flex;flex-wrap:wrap}.scientific-source-reader th,.scientific-source-reader td{min-width:7rem}}
